﻿{
  "name": "@goupdate3/opencode-mermaid",
  "version": "0.1.14",
  "description": "OpenCode plugin — render Mermaid diagrams inline in chat as SVG with collapsible source view",
  "type": "module",
"main": "dist/index.js",
  "exports": {
    ".": "./dist/index.js",
    "./tool": "./dist/tool.js"
  },
  "files": ["dist"],
  "keywords": ["opencode", "opencode-plugin", "mermaid", "diagram", "svg", "inline", "js", "mermaidjs", "graph"],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/goupdate3/opencode-mermaid"
  },
"dependencies": {},
  "peerDependencies": {
    "@opencode-ai/plugin": ">=0.13.7"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.2.26",
    "@types/bun": "latest",
    "beautiful-mermaid": "^0.1.3",
    "tsup": "^8.5.1",
    "typescript": "^5"
  },
  "scripts": {
    "build": "tsup",
    "prepublishOnly": "npm run build",
    "test": "bun test",
    "test:watch": "bun test --watch"
  }
}
